    let canvas = null;

    // Animation and smoothing variables
    let smoothedValues = {
        airspeed: 0,
        altitude: 0,
        heading: 0,
        pitch: 0,
        roll: 0
    };

    // Display constants matching screenshot layout
    const DISPLAY = {
        WIDTH: 640,
