/**
 * Element #2: Draw Crosstrack Error and Turn Rate
 */
function drawCrosstrackAndTurnRate() {
    const centerX = DISPLAY.ATTITUDE_CENTER_X;
    const y = 20;

    // Background panel
    ctx.fillStyle = COLORS.STATUS_BG;
    ctx.fillRect(centerX - 80, y, 160, 25);

    // Border
    ctx.strokeStyle = COLORS.TEXT_WHITE;
    ctx.lineWidth = 1;
    ctx.strokeRect(centerX - 80, y, 160, 25);

    // Crosstrack error display
    const crosstrack = smoothedValues.crosstrackError;
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.font = '12px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(`XTE: ${crosstrack.toFixed(1)}m`, centerX - 40, y + 16);

    // Turn rate display
    const turnRate = smoothedValues.turnRate;
    ctx.fillText(`T: ${turnRate.toFixed(1)}°/s`, centerX + 40, y + 16);
}

/**
 * Element #5: Draw Telemetry Link Quality
 */
function drawTelemetryLinkQuality() {
    const x = DISPLAY.WIDTH - 150;
    const y = 20;

    // Calculate link quality (simulated for now)
    const linkQuality = telemetryData.connected ? 95 : 0;
    const signalBars = Math.floor(linkQuality / 20);

    // Background
    ctx.fillStyle = COLORS.STATUS_BG;
    ctx.fillRect(x, y, 120, 25);

    // Border
    ctx.strokeStyle = COLORS.TEXT_WHITE;
    ctx.lineWidth = 1;
    ctx.strokeRect(x, y, 120, 25);

    // Link quality text
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.font = '12px monospace';
    ctx.textAlign = 'left';
    ctx.fillText(`LINK: ${linkQuality}%`, x + 5, y + 16);

    // Signal strength bars
    for (let i = 0; i < 5; i++) {
        const barHeight = 3 + (i * 2);
        const barColor = i < signalBars ? COLORS.TEXT_GREEN : COLORS.TEXT_WHITE;
        ctx.fillStyle = barColor;
        ctx.fillRect(x + 80 + (i * 6), y + 15 - barHeight, 4, barHeight);
    }
}

/**
 * Element #6: Draw GPS Time
 */
function drawGPSTime() {
    const x = DISPLAY.WIDTH - 120;
    const y = 50;

    // Get current time (GPS time would come from telemetry)
    const now = new Date();
    const timeString = now.toISOString().substr(11, 8); // HH:MM:SS format

    // Background
    ctx.fillStyle = COLORS.STATUS_BG;
    ctx.fillRect(x, y, 110, 20);

    // Border
    ctx.strokeStyle = COLORS.TEXT_WHITE;
    ctx.lineWidth = 1;
    ctx.strokeRect(x, y, 110, 20);

    // GPS time display
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.font = '12px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(`GPS: ${timeString}`, x + 55, y + 14);
}

/**
 * Element #9: Draw Groundspeed Display
 */
function drawGroundspeedDisplay() {
    const centerX = DISPLAY.ATTITUDE_CENTER_X;
    const y = DISPLAY.HEIGHT - 60;

    // Background
    ctx.fillStyle = COLORS.STATUS_BG;
    ctx.fillRect(centerX - 50, y, 100, 25);

    // Border
    ctx.strokeStyle = COLORS.TEXT_WHITE;
    ctx.lineWidth = 1;
    ctx.strokeRect(centerX - 50, y, 100, 25);

    // Groundspeed value
    const groundspeed = smoothedValues.groundspeed;
    ctx.fillStyle = COLORS.TEXT_GREEN;
    ctx.font = 'bold 14px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(`GS: ${Math.round(groundspeed)}kt`, centerX, y + 17);
}

/**
 * Element #10: Draw Battery Status (Upper Left)
 */
function drawBatteryStatus() {
    const x = 10;
    const y = 10;

    const voltage = telemetryData.battery_voltage || 0;
    const current = telemetryData.current || 0;

    // Background
    ctx.fillStyle = COLORS.STATUS_BG;
    ctx.fillRect(x, y, 120, 45);

    // Border
    ctx.strokeStyle = COLORS.TEXT_WHITE;
    ctx.lineWidth = 1;
    ctx.strokeRect(x, y, 120, 45);

    // Battery voltage
    ctx.fillStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
    ctx.font = '12px monospace';
    ctx.textAlign = 'left';
    ctx.fillText(`Bat: ${voltage.toFixed(2)}V`, x + 5, y + 16);

    // Current draw
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.fillText(`Cur: ${current.toFixed(1)}A`, x + 5, y + 32);

    // Battery icon
    ctx.strokeStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
    ctx.lineWidth = 2;
    ctx.strokeRect(x + 90, y + 8, 20, 12);
    ctx.fillRect(x + 110, y + 11, 3, 6);

    // Battery fill level
    const fillLevel = Math.max(0, Math.min(1, (voltage - 10) / 2.6)); // 10V to 12.6V range
    ctx.fillStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
    ctx.fillRect(x + 92, y + 10, 16 * fillLevel, 8);
}

