    ctx.font = '14px Arial';
    ctx.textAlign = 'center';

    const directions = ['N', 'E', 'S', 'W'];
    const angles = [0, 90, 180, 270];

    for (let i = 0; i < 4; i++) {
        const angle = (angles[i] - 90) * Math.PI / 180;
        const x = centerX + Math.cos(angle) * (radius - 15);
        const y = centerY + Math.sin(angle) * (radius - 15) + 5;
        ctx.fillText(directions[i], x, y);
    }

    // Draw degree markings
    for (let deg = 0; deg < 360; deg += 30) {
        const angle = (deg - 90) * Math.PI / 180;
        const startRadius = deg % 90 === 0 ? radius - 8 : radius - 4;
        const endRadius = radius;

        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = deg % 90 === 0 ? 2 : 1;
        ctx.beginPath();
