/**
 * VFR HUD Telemetry Display Module - Complete Glass Cockpit Implementation
 * Comprehensive aviation HUD with all 15 display elements as specified
 */

window.TelemetryDisplay = (function() {
    'use strict';

    // Private variables
    let telemetryData = {};
    let animationFrameId = null;
    let ctx = null;
    let canvas = null;

    // Animation and smoothing variables
    let smoothedValues = {
        airspeed: 0,
        altitude: 0,
        heading: 0,
        pitch: 0,
        roll: 0,
        groundspeed: 0,
        verticalSpeed: 0,
        crosstrackError: 0,
        turnRate: 0
    };

    // Display constants for VFR HUD layout
    const DISPLAY = {
        WIDTH: 640,
        HEIGHT: 480,
        ATTITUDE_CENTER_X: 320,  // Middle of canvas (640/2)
        ATTITUDE_CENTER_Y: 240,  // Middle of canvas (480/2)
        ATTITUDE_WIDTH: 400,
        ATTITUDE_HEIGHT: 350
    };

    // Professional aviation color scheme
    const COLORS = {
        SKY_BLUE: '#4A90E2',
        EARTH_BROWN: '#8B4513',
        HORIZON_WHITE: '#FFFFFF',
        TEXT_WHITE: '#FFFFFF',
        TEXT_GREEN: '#00FF00',
        TEXT_YELLOW: '#FFFF00',
        TEXT_RED: '#FF0000',
        WARNING_YELLOW: '#FFFF00',
        ALERT_RED: '#FF0000',
        DISPLAY_BG: '#000000',
        TICKER_BG: 'rgba(0, 0, 0, 0)',  // Transparent
        TICKER_BORDER: '#FFFFFF',
        COMPASS_BG: 'rgba(0, 0, 0, 0)', // Transparent
        STATUS_BG: 'rgba(0, 0, 0, 0.4)' // Semi-transparent for status panels only
    };

    /**
     * Initialize Clean HUD Display
     */
    function initialize() {
        console.log('Initializing Clean HUD Display...');

        canvas = document.getElementById('glass-pfd-display');
        if (!canvas) {
            console.error('HUD canvas not found');
            return;
        }

        ctx = canvas.getContext('2d');
        if (!ctx) {
            console.error('Failed to get 2D context');
            return;
        }

        setupHighDPI();
        setupEventListeners();
        startAnimationLoop();

        console.log('Clean HUD Display initialized');
    }

    /**
     * Setup High DPI Support
     */
    function setupHighDPI() {
        const dpr = window.devicePixelRatio || 1;

        canvas.width = DISPLAY.WIDTH * dpr;
        canvas.height = DISPLAY.HEIGHT * dpr;
        ctx.scale(dpr, dpr);

        canvas.style.width = DISPLAY.WIDTH + 'px';
        canvas.style.height = DISPLAY.HEIGHT + 'px';
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
        }

        window.addEventListener('resize', handleResize);
    }

    /**
     * Start Animation Loop
     */
    function startAnimationLoop() {
        function animate() {
            updateSmoothedValues();
            drawCleanHUD();
            animationFrameId = requestAnimationFrame(animate);
        }
        animate();
    }

    /**
     * Update Smoothed Values for VFR HUD
     */
    function updateSmoothedValues() {
        const smoothingFactor = 0.15;

        // Calculate current values
        const groundSpeed = Math.sqrt(
            Math.pow(telemetryData.vx || 0, 2) + 
            Math.pow(telemetryData.vy || 0, 2)
        );
        const currentAirspeed = groundSpeed * 1.94384; // m/s to knots
        const currentGroundspeed = groundSpeed * 1.94384; // m/s to knots
        const currentAltitude = (telemetryData.alt_rel || 0) * 3.28084; // m to ft
        const currentVerticalSpeed = (telemetryData.vz || 0) * 196.85; // m/s to ft/min
        const currentPitch = telemetryData.pitch || 0;
        const currentRoll = telemetryData.roll || 0;
        const currentHeading = telemetryData.hdg || 0;
        const currentCrosstrack = telemetryData.crosstrack_error || 0;
        const currentTurnRate = telemetryData.turn_rate || 0;

        // Apply exponential smoothing
        smoothedValues.airspeed = smoothedValues.airspeed + 
            (currentAirspeed - smoothedValues.airspeed) * smoothingFactor;
        smoothedValues.groundspeed = smoothedValues.groundspeed + 
            (currentGroundspeed - smoothedValues.groundspeed) * smoothingFactor;
        smoothedValues.altitude = smoothedValues.altitude + 
            (currentAltitude - smoothedValues.altitude) * smoothingFactor;
        smoothedValues.verticalSpeed = smoothedValues.verticalSpeed + 
            (currentVerticalSpeed - smoothedValues.verticalSpeed) * smoothingFactor;
        smoothedValues.pitch = smoothedValues.pitch + 
            (currentPitch - smoothedValues.pitch) * smoothingFactor;
        smoothedValues.roll = smoothedValues.roll + 
            (currentRoll - smoothedValues.roll) * smoothingFactor;
        smoothedValues.crosstrackError = smoothedValues.crosstrackError + 
            (currentCrosstrack - smoothedValues.crosstrackError) * smoothingFactor;
        smoothedValues.turnRate = smoothedValues.turnRate + 
            (currentTurnRate - smoothedValues.turnRate) * smoothingFactor;

        // Handle heading wraparound
        let headingDiff = currentHeading - smoothedValues.heading;
        if (headingDiff > 180) headingDiff -= 360;
        if (headingDiff < -180) headingDiff += 360;
        smoothedValues.heading = smoothedValues.heading + headingDiff * smoothingFactor;
        if (smoothedValues.heading < 0) smoothedValues.heading += 360;
        if (smoothedValues.heading >= 360) smoothedValues.heading -= 360;
    }

    /**
     * Draw Complete VFR HUD with all 15 elements
     */
    function drawCleanHUD() {
        // Clear display - will be covered by sky/ground, no black should show
        ctx.fillStyle = COLORS.SKY_BLUE; // Default to sky blue (will be overridden by horizon)
        ctx.fillRect(0, 0, DISPLAY.WIDTH, DISPLAY.HEIGHT);

        // Draw all 15 VFR HUD elements in proper order
        drawArtificialHorizon();          // Element #11 - Background artificial horizon
        drawAircraftAttitude();           // Element #12 - Aircraft attitude indication
        drawAirspeedTape();              // Elements #1 & #8 - Airspeed tape (left side)
        drawAltitudeTape();              // Element #7 - Altitude tape with rate of climb
        drawHeadingCompass();            // Element #3 - Heading direction compass
        drawBankAngleIndicator();        // Element #4 - Bank angle indicator
        drawCrosstrackAndTurnRate();     // Element #2 - Crosstrack error and turn rate
        drawTelemetryLinkQuality();      // Element #5 - Telemetry connection link quality
        drawGPSTime();                   // Element #6 - GPS time
        drawGroundspeedDisplay();        // Element #9 - Groundspeed
        drawBatteryStatus();             // Element #10 - Battery status (upper left)
        drawGPSStatus();                 // Element #13 - GPS status
        drawWaypointDistance();          // Element #14 - Distance to waypoint
        drawFlightMode();                // Element #15 - Current flight mode
    }

    /**
     * Element #11: Draw Artificial Horizon (Full Canvas Coverage - No Black Space)
     */
    function drawArtificialHorizon() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const pitch = smoothedValues.pitch;
        const roll = smoothedValues.roll;

        ctx.save();

        // Move to center and apply roll rotation
        ctx.translate(centerX, centerY);
        ctx.rotate(roll * Math.PI / 180);

        // Calculate pitch offset in pixels
        const pitchPixels = pitch * 4;

        // Sky (blue upper half) - MUST fill entire canvas with no black space
        ctx.fillStyle = COLORS.SKY_BLUE;
        ctx.fillRect(-DISPLAY.WIDTH * 2, -DISPLAY.HEIGHT * 2, DISPLAY.WIDTH * 4, DISPLAY.HEIGHT * 2 + pitchPixels);

        // Ground (brown lower half) - MUST fill entire canvas with no black space
        ctx.fillStyle = COLORS.EARTH_BROWN;
        ctx.fillRect(-DISPLAY.WIDTH * 2, pitchPixels, DISPLAY.WIDTH * 4, DISPLAY.HEIGHT * 2);

        // Horizon line - extend to full canvas width
        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(-DISPLAY.WIDTH * 2, pitchPixels);
        ctx.lineTo(DISPLAY.WIDTH * 2, pitchPixels);
        ctx.stroke();

        // Pitch ladder with degree markings
        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.fillStyle = COLORS.HORIZON_WHITE;
        ctx.lineWidth = 2;
        ctx.font = '12px Arial';
        ctx.textAlign = 'center';

        for (let angle = -60; angle <= 60; angle += 10) {
            if (angle === 0) continue; // Skip horizon line

            const y = pitchPixels - (angle * 4);
            const lineLength = Math.abs(angle) % 20 === 0 ? 80 : 40;

            // Pitch line
            ctx.beginPath();
            ctx.moveTo(-lineLength/2, y);
            ctx.lineTo(lineLength/2, y);
            ctx.stroke();

            // Pitch numbers for major lines
            if (Math.abs(angle) % 20 === 0) {
                ctx.fillText(Math.abs(angle).toString(), -lineLength/2 - 20, y + 4);
                ctx.fillText(Math.abs(angle).toString(), lineLength/2 + 20, y + 4);
            }
        }

        ctx.restore();
    }

    /**
     * Element #12: Draw Aircraft Attitude Indication (Fixed Yellow Symbol)
     */
    function drawAircraftAttitude() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;

        // Aircraft symbol (fixed to screen, not affected by attitude)
        ctx.strokeStyle = COLORS.TEXT_YELLOW;
        ctx.fillStyle = COLORS.TEXT_YELLOW;
        ctx.lineWidth = 4;

        // Main horizontal reference line
        ctx.beginPath();
        ctx.moveTo(centerX - 50, centerY);
        ctx.lineTo(centerX - 15, centerY);
        ctx.moveTo(centerX + 50, centerY);
        ctx.lineTo(centerX + 15, centerY);
        ctx.stroke();

        // Center triangle/arrow pointing forward
        ctx.beginPath();
        ctx.moveTo(centerX, centerY - 8);
        ctx.lineTo(centerX - 8, centerY + 8);
        ctx.lineTo(centerX + 8, centerY + 8);
        ctx.closePath();
        ctx.fill();

        // Center dot
        ctx.beginPath();
        ctx.arc(centerX, centerY, 3, 0, Math.PI * 2);
        ctx.fill();
    }

    /**
     * Elements #1 & #8: Draw Airspeed Tape (Left Side Vertical Tape)
     */
    function drawAirspeedTape() {
        const x = 10;
        const width = 90;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const height = 300;

        // No background - transparent overlay on sky/ground
        // Border only for definition
        ctx.strokeStyle = COLORS.TICKER_BORDER;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, centerY - height/2, width, height);

        // Speed scale
        const airspeed = smoothedValues.airspeed;
        const tickSpacing = 15; // pixels per 5 knots
        const speedPerTick = 5;

        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'right';

        for (let i = -10; i <= 10; i++) {
            const speed = Math.round((airspeed + (i * speedPerTick)) / speedPerTick) * speedPerTick;
            if (speed < 0) continue;

            const tickY = centerY + (i * tickSpacing);
            if (tickY < centerY - height/2 || tickY > centerY + height/2) continue;

            // Major tick marks every 10 knots
            if (speed % 10 === 0) {
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(x + width - 15, tickY);
                ctx.lineTo(x + width - 5, tickY);
                ctx.stroke();

                // Speed labels
                ctx.fillText(speed.toString(), x + width - 20, tickY + 4);
            } else {
                // Minor tick marks
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(x + width - 10, tickY);
                ctx.lineTo(x + width - 5, tickY);
                ctx.stroke();
            }
        }

        // Current airspeed indicator (highlighted box with transparent background)
        const currentY = centerY;
        ctx.strokeStyle = COLORS.TEXT_GREEN;
        ctx.lineWidth = 2;
        ctx.strokeRect(x + width - 35, currentY - 10, 30, 20);

        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.font = 'bold 14px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(Math.round(airspeed).toString(), x + width - 20, currentY + 5);

        // Speed label
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('AIRSPEED', x + width/2, x + 15);
    }

    /**
     * Element #7: Draw Altitude Tape with Rate of Climb (Right Side)
     */
    function drawAltitudeTape() {
        const x = DISPLAY.WIDTH - 110;
        const width = 100;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const height = 300;

        // No background - transparent overlay on sky/ground
        // Border only for definition
        ctx.strokeStyle = COLORS.TICKER_BORDER;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, centerY - height/2, width, height);

        // Altitude scale
        const altitude = smoothedValues.altitude;
        const tickSpacing = 12; // pixels per 20 ft
        const altPerTick = 20;

        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'left';

        for (let i = -12; i <= 12; i++) {
            const alt = Math.round((altitude + (i * altPerTick)) / altPerTick) * altPerTick;
            const tickY = centerY - (i * tickSpacing); // Inverted for altitude (up is positive)

            if (tickY < centerY - height/2 || tickY > centerY + height/2) continue;

            // Major tick marks every 100 feet
            if (alt % 100 === 0) {
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(x + 5, tickY);
                ctx.lineTo(x + 20, tickY);
                ctx.stroke();

                // Altitude labels
                ctx.fillText(alt.toString(), x + 25, tickY + 4);
            } else if (alt % 50 === 0) {
                // Medium tick marks every 50 feet
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(x + 5, tickY);
                ctx.lineTo(x + 15, tickY);
                ctx.stroke();
            } else {
                // Minor tick marks
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(x + 5, tickY);
                ctx.lineTo(x + 10, tickY);
                ctx.stroke();
            }
        }

        // Current altitude indicator (highlighted box with transparent background)
        const currentY = centerY;
        ctx.strokeStyle = COLORS.TEXT_GREEN;
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 25, currentY - 10, 45, 20);

        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.font = 'bold 14px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(Math.round(altitude).toString(), x + 47, currentY + 5);

        // Blue rate of climb bar (Element #7 specific feature)
        const vsIndicator = Math.max(-height/4, Math.min(height/4, smoothedValues.verticalSpeed * 0.1));
        if (Math.abs(vsIndicator) > 2) {
            ctx.fillStyle = '#0066FF'; // Blue for rate of climb
            ctx.fillRect(x + 75, currentY - vsIndicator/2, 8, Math.abs(vsIndicator));
        }

        // Vertical speed numeric display
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '10px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`${Math.round(smoothedValues.verticalSpeed)}`, x + 85, centerY + height/2 - 10);
        ctx.fillText('VS', x + 85, centerY + height/2 + 5);

        // Altitude label
        ctx.font = '10px Arial';
        ctx.fillText('ALTITUDE', x + width/2, centerY - height/2 - 5);
    }

    /**
     * Element #3: Draw Heading Direction - Traditional Compass Rose (Top Center)
     */
    function drawHeadingCompass() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = 60;
        const roseSize = 80;
        const heading = smoothedValues.heading;

        // No background - transparent overlay

        // Traditional compass rose design with N, E, S, W points
        ctx.save();
        ctx.translate(centerX, centerY);
        ctx.rotate(-heading * Math.PI / 180); // Rotate compass rose, not aircraft

        // Draw cardinal direction markers (transparent background)
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center';
        ctx.textBaseline = 'middle';

        // North (top)
        ctx.fillText('N', 0, -roseSize/2 - 15);

        // East (right)
        ctx.fillText('E', roseSize/2 + 15, 0);

        // South (bottom)
        ctx.fillText('S', 0, roseSize/2 + 15);

        // West (left)
        ctx.fillText('W', -roseSize/2 - 15, 0);

        // Draw intercardinal directions
        ctx.font = '12px Arial';
        ctx.fillText('NE', roseSize/2 * 0.707, -roseSize/2 * 0.707 - 10);
        ctx.fillText('SE', roseSize/2 * 0.707, roseSize/2 * 0.707 + 10);
        ctx.fillText('SW', -roseSize/2 * 0.707, roseSize/2 * 0.707 + 10);
        ctx.fillText('NW', -roseSize/2 * 0.707, -roseSize/2 * 0.707 - 10);

        // Draw compass rose lines
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 2;

        // Main cross (N-S, E-W)
        ctx.beginPath();
        ctx.moveTo(0, -roseSize/2);
        ctx.lineTo(0, roseSize/2);
        ctx.moveTo(-roseSize/2, 0);
        ctx.lineTo(roseSize/2, 0);
        ctx.stroke();

        // Diagonal cross (NE-SW, NW-SE)
        ctx.lineWidth = 1;
        ctx.beginPath();
        ctx.moveTo(-roseSize/2 * 0.707, -roseSize/2 * 0.707);
        ctx.lineTo(roseSize/2 * 0.707, roseSize/2 * 0.707);
        ctx.moveTo(roseSize/2 * 0.707, -roseSize/2 * 0.707);
        ctx.lineTo(-roseSize/2 * 0.707, roseSize/2 * 0.707);
        ctx.stroke();

        // Draw degree tick marks around rose
        for (let deg = 0; deg < 360; deg += 10) {
            const angle = deg * Math.PI / 180;
            const tickLength = deg % 30 === 0 ? 8 : 4;
            const startRadius = roseSize/2 - 5;
            const endRadius = startRadius - tickLength;

            ctx.strokeStyle = COLORS.TEXT_WHITE;
            ctx.lineWidth = deg % 90 === 0 ? 2 : 1;
            ctx.beginPath();
            ctx.moveTo(
                Math.cos(angle) * startRadius,
                Math.sin(angle) * startRadius
            );
            ctx.lineTo(
                Math.cos(angle) * endRadius,
                Math.sin(angle) * endRadius
            );
            ctx.stroke();
        }

        ctx.restore();

        // Fixed aircraft heading indicator (always points up)
        ctx.fillStyle = COLORS.TEXT_YELLOW;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY - roseSize/2 - 5);
        ctx.lineTo(centerX - 6, centerY - roseSize/2 + 5);
        ctx.lineTo(centerX + 6, centerY - roseSize/2 + 5);
        ctx.closePath();
        ctx.fill();

        // Digital heading display (fixed position)
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = 'bold 16px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`${Math.round(heading).toString().padStart(3, '0')}°`, centerX, centerY + roseSize/2 + 25);
    }

    /**
     * Element #4: Draw Bank Angle Indicator
     */
    function drawBankAngleIndicator() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const radius = 180;

        // Bank angle scale (arc at top of attitude indicator)
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 2;

        // Draw bank angle markings
        const bankAngles = [-60, -45, -30, -20, -10, 0, 10, 20, 30, 45, 60];

        for (let i = 0; i < bankAngles.length; i++) {
            const angle = bankAngles[i];
            const angleRad = (angle - 90) * Math.PI / 180;
            const tickLength = Math.abs(angle) % 30 === 0 ? 15 : 8;

            ctx.beginPath();
            ctx.moveTo(
                centerX + Math.cos(angleRad) * radius,
                centerY + Math.sin(angleRad) * radius
            );
            ctx.lineTo(
                centerX + Math.cos(angleRad) * (radius - tickLength),
                centerY + Math.sin(angleRad) * (radius - tickLength)
            );
            ctx.stroke();

            // Bank angle labels for major markings
            if (Math.abs(angle) % 30 === 0 && angle !== 0) {
                ctx.fillStyle = COLORS.TEXT_WHITE;
                ctx.font = '10px Arial';
                ctx.textAlign = 'center';
                const labelX = centerX + Math.cos(angleRad) * (radius - 25);
                const labelY = centerY + Math.sin(angleRad) * (radius - 25) + 3;
                ctx.fillText(Math.abs(angle).toString(), labelX, labelY);
            }
        }

        // Current bank angle indicator (triangle)
        const currentRoll = smoothedValues.roll;
        const rollRad = (currentRoll - 90) * Math.PI / 180;

        ctx.fillStyle = COLORS.TEXT_YELLOW;
        ctx.beginPath();
        const indicatorX = centerX + Math.cos(rollRad) * radius;
        const indicatorY = centerY + Math.sin(rollRad) * radius;
        ctx.moveTo(indicatorX, indicatorY);
        ctx.lineTo(indicatorX - 5, indicatorY - 10);
        ctx.lineTo(indicatorX + 5, indicatorY - 10);
        ctx.closePath();
        ctx.fill();
    }

    /**
     * Element #2: Draw Crosstrack Error and Turn Rate
     */
    function drawCrosstrackAndTurnRate() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const y = 20;

        // Background panel
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(centerX - 80, y, 160, 25);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(centerX - 80, y, 160, 25);

        // Crosstrack error display
        const crosstrack = smoothedValues.crosstrackError;
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`XTE: ${crosstrack.toFixed(1)}m`, centerX - 40, y + 16);

        // Turn rate display
        const turnRate = smoothedValues.turnRate;
        ctx.fillText(`T: ${turnRate.toFixed(1)}°/s`, centerX + 40, y + 16);
    }

    /**
     * Element #5: Draw Telemetry Link Quality
     */
    function drawTelemetryLinkQuality() {
        const x = DISPLAY.WIDTH - 150;
        const y = 20;

        // Calculate link quality (simulated for now)
        const linkQuality = telemetryData.connected ? 95 : 0;
        const signalBars = Math.floor(linkQuality / 20);

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 120, 25);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 120, 25);

        // Link quality text
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`LINK: ${linkQuality}%`, x + 5, y + 16);

        // Signal strength bars
        for (let i = 0; i < 5; i++) {
            const barHeight = 3 + (i * 2);
            const barColor = i < signalBars ? COLORS.TEXT_GREEN : COLORS.TEXT_WHITE;
            ctx.fillStyle = barColor;
            ctx.fillRect(x + 80 + (i * 6), y + 15 - barHeight, 4, barHeight);
        }
    }

    /**
     * Element #6: Draw GPS Time
     */
    function drawGPSTime() {
        const x = DISPLAY.WIDTH - 120;
        const y = 50;

        // Get current time (GPS time would come from telemetry)
        const now = new Date();
        const timeString = now.toISOString().substr(11, 8); // HH:MM:SS format

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 110, 20);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 110, 20);

        // GPS time display
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`GPS: ${timeString}`, x + 55, y + 14);
    }

    /**
     * Element #9: Draw Groundspeed Display
     */
    function drawGroundspeedDisplay() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const y = DISPLAY.HEIGHT - 60;

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(centerX - 50, y, 100, 25);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(centerX - 50, y, 100, 25);

        // Groundspeed value
        const groundspeed = smoothedValues.groundspeed;
        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.font = 'bold 14px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`GS: ${Math.round(groundspeed)}kt`, centerX, y + 17);
    }

    /**
     * Element #10: Draw Battery Status (Upper Left)
     */
    function drawBatteryStatus() {
        const x = 10;
        const y = 10;

        const voltage = telemetryData.battery_voltage || 0;
        const current = telemetryData.current || 0;

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 120, 45);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 120, 45);

        // Battery voltage
        ctx.fillStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
        ctx.font = '12px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`Bat: ${voltage.toFixed(2)}V`, x + 5, y + 16);

        // Current draw
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.fillText(`Cur: ${current.toFixed(1)}A`, x + 5, y + 32);

        // Battery icon
        ctx.strokeStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 90, y + 8, 20, 12);
        ctx.fillRect(x + 110, y + 11, 3, 6);

        // Battery fill level
        const fillLevel = Math.max(0, Math.min(1, (voltage - 10) / 2.6)); // 10V to 12.6V range
        ctx.fillStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
        ctx.fillRect(x + 92, y + 10, 16 * fillLevel, 8);
    }

    /**
     * Element #13: Draw GPS Status
     */
    function drawGPSStatus() {
        const x = 10;
        const y = DISPLAY.HEIGHT - 80;

        // Determine GPS status
        const lat = telemetryData.lat || 0;
        const lon = telemetryData.lon || 0;
        const numSats = telemetryData.gps_nsat || 0;

        let gpsStatus = 'NO FIX';
        let statusColor = COLORS.ALERT_RED;

        if (numSats >= 6) {
            gpsStatus = '3D FIX';
            statusColor = COLORS.TEXT_GREEN;
        } else if (numSats >= 4) {
            gpsStatus = '2D FIX';
            statusColor = COLORS.WARNING_YELLOW;
        }

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 120, 35);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 120, 35);

        // GPS status text
        ctx.fillStyle = statusColor;
        ctx.font = 'bold 12px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`GPS: ${gpsStatus}`, x + 5, y + 16);

        // Satellite count
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '10px monospace';
        ctx.fillText(`Sats: ${numSats}`, x + 5, y + 30);

        // Position display (6 decimal precision)
        ctx.font = '8px monospace';
        if (lat !== 0 && lon !== 0) {
            ctx.fillText(`${lat.toFixed(6)}`, x + 60, y + 16);
            ctx.fillText(`${lon.toFixed(6)}`, x + 60, y + 26);
        } else {
            ctx.fillText('---.------', x + 60, y + 16);
            ctx.fillText('---.------', x + 60, y + 26);
        }
    }

    /**
     * Element #14: Draw Distance to Waypoint and Current Waypoint Number
     */
    function drawWaypointDistance() {
        const x = DISPLAY.WIDTH - 140;
        const y = DISPLAY.HEIGHT - 80;

        // Waypoint information (would come from mission data)
        const currentWaypoint = telemetryData.current_waypoint || 0;
        const waypointDistance = telemetryData.waypoint_distance || 0;

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 130, 35);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 130, 35);

        // Waypoint info
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'left';

        if (currentWaypoint > 0) {
            ctx.fillText(`WPT ${currentWaypoint}`, x + 5, y + 16);
            ctx.fillText(`${waypointDistance.toFixed(1)} m`, x + 5, y + 30);
        } else {
            ctx.fillText('NO WPT', x + 5, y + 16);
            ctx.fillText('--- m', x + 5, y + 30);
        }

        // Waypoint icon
        ctx.strokeStyle = COLORS.TEXT_GREEN;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(x + 100, y + 18, 8, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.beginPath();
        ctx.arc(x + 100, y + 18, 3, 0, Math.PI * 2);
        ctx.fill();
    }

    /**
     * Element #15: Draw Current Flight Mode
     */
    function drawFlightMode() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const y = DISPLAY.HEIGHT - 40;

        const armed = telemetryData.armed;
        const mode = telemetryData.mode || 'UNKNOWN';
        const armedText = armed ? 'ARMED' : 'DISARMED';

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(centerX - 100, y, 200, 30);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(centerX - 100, y, 200, 30);

        // Flight mode
        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(mode, centerX - 50, y + 20);

        // Armed status
        const armedColor = armed ? COLORS.ALERT_RED : COLORS.TEXT_GREEN;
        ctx.fillStyle = armedColor;
        ctx.font = 'bold 14px Arial';
        ctx.fillText(armedText, centerX + 50, y + 20);
    }

    /**
     * Handle Telemetry Update
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail || event;
        if (data) {
            telemetryData = { ...telemetryData, ...data };
        }
    }

    /**
     * Handle Connection Change
     */
    function handleConnectionChange(event) {
        const data = event.detail || event;
        if (data && !data.connected) {
            telemetryData = {};
        }
    }

    /**
     * Handle Resize
     */
    function handleResize() {
        setTimeout(() => {
            setupHighDPI();
        }, 100);
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,
        getTelemetryData: () => ({ ...telemetryData }),
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: handleResize,
        destroy: () => {
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
            }
        }
    };
})();

/**
 * VFR HUD Telemetry Display Module - Complete Glass Cockpit Implementation
 * Comprehensive aviation HUD with all 15 display elements as specified
 */

window.TelemetryDisplay = (function() {
    'use strict';

    // Private variables
    let telemetryData = {};
    let animationFrameId = null;
    let ctx = null;
    let canvas = null;

    // Animation and smoothing variables
    let smoothedValues = {
        airspeed: 0,
        altitude: 0,
        heading: 0,
        pitch: 0,
        roll: 0,
        groundspeed: 0,
        verticalSpeed: 0,
        crosstrackError: 0,
        turnRate: 0
    };

    // Display constants for VFR HUD layout
    const DISPLAY = {
        WIDTH: 640,
        HEIGHT: 480,
        ATTITUDE_CENTER_X: 320,  // Middle of canvas (640/2)
        ATTITUDE_CENTER_Y: 240,  // Middle of canvas (480/2)
        ATTITUDE_WIDTH: 400,
        ATTITUDE_HEIGHT: 350
    };

    // Professional aviation color scheme
    const COLORS = {
        SKY_BLUE: '#4A90E2',
        EARTH_BROWN: '#8B4513',
        HORIZON_WHITE: '#FFFFFF',
        TEXT_WHITE: '#FFFFFF',
        TEXT_GREEN: '#00FF00',
        TEXT_YELLOW: '#FFFF00',
        TEXT_RED: '#FF0000',
        WARNING_YELLOW: '#FFFF00',
        ALERT_RED: '#FF0000',
        DISPLAY_BG: '#000000',
        TICKER_BG: 'rgba(0, 0, 0, 0)',  // Transparent
        TICKER_BORDER: '#FFFFFF',
        COMPASS_BG: 'rgba(0, 0, 0, 0)', // Transparent
        STATUS_BG: 'rgba(0, 0, 0, 0.4)' // Semi-transparent for status panels only
    };

    /**
     * Initialize Clean HUD Display
     */
    function initialize() {
        console.log('Initializing Clean HUD Display...');

        canvas = document.getElementById('glass-pfd-display');
        if (!canvas) {
            console.error('HUD canvas not found');
            return;
        }

        ctx = canvas.getContext('2d');
        if (!ctx) {
            console.error('Failed to get 2D context');
            return;
        }

        setupHighDPI();
        setupEventListeners();
        startAnimationLoop();

        console.log('Clean HUD Display initialized');
    }

    /**
     * Setup High DPI Support
     */
    function setupHighDPI() {
        const dpr = window.devicePixelRatio || 1;

        canvas.width = DISPLAY.WIDTH * dpr;
        canvas.height = DISPLAY.HEIGHT * dpr;
        ctx.scale(dpr, dpr);

        canvas.style.width = DISPLAY.WIDTH + 'px';
        canvas.style.height = DISPLAY.HEIGHT + 'px';
    }

    /**
     * Setup Event Listeners
     */
    function setupEventListeners() {
        if (window.WebGCS && window.WebGCS.eventBus) {
            window.WebGCS.eventBus.addEventListener('telemetry_updated', handleTelemetryUpdate);
            window.WebGCS.eventBus.addEventListener('connection_changed', handleConnectionChange);
        }

        window.addEventListener('resize', handleResize);
    }

    /**
     * Start Animation Loop
     */
    function startAnimationLoop() {
        function animate() {
            updateSmoothedValues();
            drawCleanHUD();
            animationFrameId = requestAnimationFrame(animate);
        }
        animate();
    }

    /**
     * Update Smoothed Values for VFR HUD
     */
    function updateSmoothedValues() {
        const smoothingFactor = 0.15;

        // Calculate current values
        const groundSpeed = Math.sqrt(
            Math.pow(telemetryData.vx || 0, 2) + 
            Math.pow(telemetryData.vy || 0, 2)
        );
        const currentAirspeed = groundSpeed * 1.94384; // m/s to knots
        const currentGroundspeed = groundSpeed * 1.94384; // m/s to knots
        const currentAltitude = (telemetryData.alt_rel || 0) * 3.28084; // m to ft
        const currentVerticalSpeed = (telemetryData.vz || 0) * 196.85; // m/s to ft/min
        const currentPitch = telemetryData.pitch || 0;
        const currentRoll = telemetryData.roll || 0;
        const currentHeading = telemetryData.hdg || 0;
        const currentCrosstrack = telemetryData.crosstrack_error || 0;
        const currentTurnRate = telemetryData.turn_rate || 0;

        // Apply exponential smoothing
        smoothedValues.airspeed = smoothedValues.airspeed + 
            (currentAirspeed - smoothedValues.airspeed) * smoothingFactor;
        smoothedValues.groundspeed = smoothedValues.groundspeed + 
            (currentGroundspeed - smoothedValues.groundspeed) * smoothingFactor;
        smoothedValues.altitude = smoothedValues.altitude + 
            (currentAltitude - smoothedValues.altitude) * smoothingFactor;
        smoothedValues.verticalSpeed = smoothedValues.verticalSpeed + 
            (currentVerticalSpeed - smoothedValues.verticalSpeed) * smoothingFactor;
        smoothedValues.pitch = smoothedValues.pitch + 
            (currentPitch - smoothedValues.pitch) * smoothingFactor;
        smoothedValues.roll = smoothedValues.roll + 
            (currentRoll - smoothedValues.roll) * smoothingFactor;
        smoothedValues.crosstrackError = smoothedValues.crosstrackError + 
            (currentCrosstrack - smoothedValues.crosstrackError) * smoothingFactor;
        smoothedValues.turnRate = smoothedValues.turnRate + 
            (currentTurnRate - smoothedValues.turnRate) * smoothingFactor;

        // Handle heading wraparound
        let headingDiff = currentHeading - smoothedValues.heading;
        if (headingDiff > 180) headingDiff -= 360;
        if (headingDiff < -180) headingDiff += 360;
        smoothedValues.heading = smoothedValues.heading + headingDiff * smoothingFactor;
        if (smoothedValues.heading < 0) smoothedValues.heading += 360;
        if (smoothedValues.heading >= 360) smoothedValues.heading -= 360;
    }

    /**
     * Draw Complete VFR HUD with all 15 elements
     */
    function drawCleanHUD() {
        // Clear display - will be covered by sky/ground, no black should show
        ctx.fillStyle = COLORS.SKY_BLUE; // Default to sky blue (will be overridden by horizon)
        ctx.fillRect(0, 0, DISPLAY.WIDTH, DISPLAY.HEIGHT);

        // Draw all 15 VFR HUD elements in proper order
        drawArtificialHorizon();          // Element #11 - Background artificial horizon
        drawAircraftAttitude();           // Element #12 - Aircraft attitude indication
        drawAirspeedTape();              // Elements #1 & #8 - Airspeed tape (left side)
        drawAltitudeTape();              // Element #7 - Altitude tape with rate of climb
        drawHeadingCompass();            // Element #3 - Heading direction compass
        drawBankAngleIndicator();        // Element #4 - Bank angle indicator
        drawCrosstrackAndTurnRate();     // Element #2 - Crosstrack error and turn rate
        drawTelemetryLinkQuality();      // Element #5 - Telemetry connection link quality
        drawGPSTime();                   // Element #6 - GPS time
        drawGroundspeedDisplay();        // Element #9 - Groundspeed
        drawBatteryStatus();             // Element #10 - Battery status (upper left)
        drawGPSStatus();                 // Element #13 - GPS status
        drawWaypointDistance();          // Element #14 - Distance to waypoint
        drawFlightMode();                // Element #15 - Current flight mode
    }

    /**
     * Element #11: Draw Artificial Horizon (Full Canvas Coverage - No Black Space)
     */
    function drawArtificialHorizon() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const pitch = smoothedValues.pitch;
        const roll = smoothedValues.roll;

        ctx.save();

        // Move to center and apply roll rotation
        ctx.translate(centerX, centerY);
        ctx.rotate(roll * Math.PI / 180);

        // Calculate pitch offset in pixels
        const pitchPixels = pitch * 4;

        // Sky (blue upper half) - MUST fill entire canvas with no black space
        ctx.fillStyle = COLORS.SKY_BLUE;
        ctx.fillRect(-DISPLAY.WIDTH * 2, -DISPLAY.HEIGHT * 2, DISPLAY.WIDTH * 4, DISPLAY.HEIGHT * 2 + pitchPixels);

        // Ground (brown lower half) - MUST fill entire canvas with no black space
        ctx.fillStyle = COLORS.EARTH_BROWN;
        ctx.fillRect(-DISPLAY.WIDTH * 2, pitchPixels, DISPLAY.WIDTH * 4, DISPLAY.HEIGHT * 2);

        // Horizon line - extend to full canvas width
        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.lineWidth = 3;
        ctx.beginPath();
        ctx.moveTo(-DISPLAY.WIDTH * 2, pitchPixels);
        ctx.lineTo(DISPLAY.WIDTH * 2, pitchPixels);
        ctx.stroke();

        // Pitch ladder with degree markings
        ctx.strokeStyle = COLORS.HORIZON_WHITE;
        ctx.fillStyle = COLORS.HORIZON_WHITE;
        ctx.lineWidth = 2;
        ctx.font = '12px Arial';
        ctx.textAlign = 'center';

        for (let angle = -60; angle <= 60; angle += 10) {
            if (angle === 0) continue; // Skip horizon line

            const y = pitchPixels - (angle * 4);
            const lineLength = Math.abs(angle) % 20 === 0 ? 80 : 40;

            // Pitch line
            ctx.beginPath();
            ctx.moveTo(-lineLength/2, y);
            ctx.lineTo(lineLength/2, y);
            ctx.stroke();

            // Pitch numbers for major lines
            if (Math.abs(angle) % 20 === 0) {
                ctx.fillText(Math.abs(angle).toString(), -lineLength/2 - 20, y + 4);
                ctx.fillText(Math.abs(angle).toString(), lineLength/2 + 20, y + 4);
            }
        }

        ctx.restore();
    }

    /**
     * Element #12: Draw Aircraft Attitude Indication (Fixed Yellow Symbol)
     */
    function drawAircraftAttitude() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;

        // Aircraft symbol (fixed to screen, not affected by attitude)
        ctx.strokeStyle = COLORS.TEXT_YELLOW;
        ctx.fillStyle = COLORS.TEXT_YELLOW;
        ctx.lineWidth = 4;

        // Main horizontal reference line
        ctx.beginPath();
        ctx.moveTo(centerX - 50, centerY);
        ctx.lineTo(centerX - 15, centerY);
        ctx.moveTo(centerX + 50, centerY);
        ctx.lineTo(centerX + 15, centerY);
        ctx.stroke();

        // Center triangle/arrow pointing forward
        ctx.beginPath();
        ctx.moveTo(centerX, centerY - 8);
        ctx.lineTo(centerX - 8, centerY + 8);
        ctx.lineTo(centerX + 8, centerY + 8);
        ctx.closePath();
        ctx.fill();

        // Center dot
        ctx.beginPath();
        ctx.arc(centerX, centerY, 3, 0, Math.PI * 2);
        ctx.fill();
    }

    /**
     * Elements #1 & #8: Draw Airspeed Tape (Left Side Vertical Tape)
     */
    function drawAirspeedTape() {
        const x = 10;
        const width = 90;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const height = 300;

        // No background - transparent overlay on sky/ground
        // Border only for definition
        ctx.strokeStyle = COLORS.TICKER_BORDER;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, centerY - height/2, width, height);

        // Speed scale
        const airspeed = smoothedValues.airspeed;
        const tickSpacing = 15; // pixels per 5 knots
        const speedPerTick = 5;

        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'right';

        for (let i = -10; i <= 10; i++) {
            const speed = Math.round((airspeed + (i * speedPerTick)) / speedPerTick) * speedPerTick;
            if (speed < 0) continue;

            const tickY = centerY + (i * tickSpacing);
            if (tickY < centerY - height/2 || tickY > centerY + height/2) continue;

            // Major tick marks every 10 knots
            if (speed % 10 === 0) {
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(x + width - 15, tickY);
                ctx.lineTo(x + width - 5, tickY);
                ctx.stroke();

                // Speed labels
                ctx.fillText(speed.toString(), x + width - 20, tickY + 4);
            } else {
                // Minor tick marks
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(x + width - 10, tickY);
                ctx.lineTo(x + width - 5, tickY);
                ctx.stroke();
            }
        }

        // Current airspeed indicator (highlighted box with transparent background)
        const currentY = centerY;
        ctx.strokeStyle = COLORS.TEXT_GREEN;
        ctx.lineWidth = 2;
        ctx.strokeRect(x + width - 35, currentY - 10, 30, 20);

        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.font = 'bold 14px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(Math.round(airspeed).toString(), x + width - 20, currentY + 5);

        // Speed label
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '10px Arial';
        ctx.textAlign = 'center';
        ctx.fillText('AIRSPEED', x + width/2, x + 15);
    }

    /**
     * Element #7: Draw Altitude Tape with Rate of Climb (Right Side)
     */
    function drawAltitudeTape() {
        const x = DISPLAY.WIDTH - 110;
        const width = 100;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const height = 300;

        // No background - transparent overlay on sky/ground
        // Border only for definition
        ctx.strokeStyle = COLORS.TICKER_BORDER;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, centerY - height/2, width, height);

        // Altitude scale
        const altitude = smoothedValues.altitude;
        const tickSpacing = 12; // pixels per 20 ft
        const altPerTick = 20;

        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'left';

        for (let i = -12; i <= 12; i++) {
            const alt = Math.round((altitude + (i * altPerTick)) / altPerTick) * altPerTick;
            const tickY = centerY - (i * tickSpacing); // Inverted for altitude (up is positive)

            if (tickY < centerY - height/2 || tickY > centerY + height/2) continue;

            // Major tick marks every 100 feet
            if (alt % 100 === 0) {
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(x + 5, tickY);
                ctx.lineTo(x + 20, tickY);
                ctx.stroke();

                // Altitude labels
                ctx.fillText(alt.toString(), x + 25, tickY + 4);
            } else if (alt % 50 === 0) {
                // Medium tick marks every 50 feet
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(x + 5, tickY);
                ctx.lineTo(x + 15, tickY);
                ctx.stroke();
            } else {
                // Minor tick marks
                ctx.strokeStyle = COLORS.TEXT_WHITE;
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(x + 5, tickY);
                ctx.lineTo(x + 10, tickY);
                ctx.stroke();
            }
        }

        // Current altitude indicator (highlighted box with transparent background)
        const currentY = centerY;
        ctx.strokeStyle = COLORS.TEXT_GREEN;
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 25, currentY - 10, 45, 20);

        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.font = 'bold 14px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(Math.round(altitude).toString(), x + 47, currentY + 5);

        // Blue rate of climb bar (Element #7 specific feature)
        const vsIndicator = Math.max(-height/4, Math.min(height/4, smoothedValues.verticalSpeed * 0.1));
        if (Math.abs(vsIndicator) > 2) {
            ctx.fillStyle = '#0066FF'; // Blue for rate of climb
            ctx.fillRect(x + 75, currentY - vsIndicator/2, 8, Math.abs(vsIndicator));
        }

        // Vertical speed numeric display
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '10px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`${Math.round(smoothedValues.verticalSpeed)}`, x + 85, centerY + height/2 - 10);
        ctx.fillText('VS', x + 85, centerY + height/2 + 5);

        // Altitude label
        ctx.font = '10px Arial';
        ctx.fillText('ALTITUDE', x + width/2, centerY - height/2 - 5);
    }

    /**
     * Element #3: Draw Heading Direction - Horizontal Heading Tape (Top Center)
     */
    function drawHeadingCompass() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = 30;
        const tapeWidth = 400;
        const tapeHeight = 40;
        const heading = smoothedValues.heading;

        // Draw horizontal heading tape background (no black background)
        const tapeX = centerX - tapeWidth/2;

        // Heading tape markings
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px Arial';
        ctx.textAlign = 'center';
        ctx.lineWidth = 1;

        // Calculate visible heading range
        const degreesPerPixel = 0.5; // 0.5 degrees per pixel
        const halfRange = (tapeWidth/2) * degreesPerPixel;

        // Draw heading markings
        for (let deg = Math.floor(heading - halfRange); deg <= Math.ceil(heading + halfRange); deg += 10) {
            let displayDeg = deg;
            if (displayDeg < 0) displayDeg += 360;
            if (displayDeg >= 360) displayDeg -= 360;

            const pixelOffset = (deg - heading) / degreesPerPixel;
            const x = centerX + pixelOffset;

            if (x < tapeX || x > tapeX + tapeWidth) continue;

            // Major tick marks every 30 degrees
            if (displayDeg % 30 === 0) {
                ctx.lineWidth = 2;
                ctx.beginPath();
                ctx.moveTo(x, centerY - 15);
                ctx.lineTo(x, centerY + 5);
                ctx.stroke();

                // Cardinal direction labels
                let label = displayDeg.toString();
                if (displayDeg === 0) label = 'N';
                else if (displayDeg === 90) label = 'E';
                else if (displayDeg === 180) label = 'S';
                else if (displayDeg === 270) label = 'W';
                else label = (displayDeg / 10).toString();

                ctx.fillText(label, x, centerY - 20);
            } else {
                // Minor tick marks
                ctx.lineWidth = 1;
                ctx.beginPath();
                ctx.moveTo(x, centerY - 10);
                ctx.lineTo(x, centerY + 5);
                ctx.stroke();
            }
        }

        // Center heading indicator (fixed yellow triangle pointing down)
        ctx.fillStyle = COLORS.TEXT_YELLOW;
        ctx.beginPath();
        ctx.moveTo(centerX, centerY + 8);
        ctx.lineTo(centerX - 8, centerY - 5);
        ctx.lineTo(centerX + 8, centerY - 5);
        ctx.closePath();
        ctx.fill();

        // Digital heading display (no background - transparent text)
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = 'bold 16px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`${Math.round(heading).toString().padStart(3, '0')}°`, centerX, centerY + 30);
    }

    /**
     * Element #4: Draw Bank Angle Indicator
     */
    function drawBankAngleIndicator() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const centerY = DISPLAY.ATTITUDE_CENTER_Y;
        const radius = 180;

        // Bank angle scale (arc at top of attitude indicator)
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 2;

        // Draw bank angle markings
        const bankAngles = [-60, -45, -30, -20, -10, 0, 10, 20, 30, 45, 60];

        for (let i = 0; i < bankAngles.length; i++) {
            const angle = bankAngles[i];
            const angleRad = (angle - 90) * Math.PI / 180;
            const tickLength = Math.abs(angle) % 30 === 0 ? 15 : 8;

            ctx.beginPath();
            ctx.moveTo(
                centerX + Math.cos(angleRad) * radius,
                centerY + Math.sin(angleRad) * radius
            );
            ctx.lineTo(
                centerX + Math.cos(angleRad) * (radius - tickLength),
                centerY + Math.sin(angleRad) * (radius - tickLength)
            );
            ctx.stroke();

            // Bank angle labels for major markings
            if (Math.abs(angle) % 30 === 0 && angle !== 0) {
                ctx.fillStyle = COLORS.TEXT_WHITE;
                ctx.font = '10px Arial';
                ctx.textAlign = 'center';
                const labelX = centerX + Math.cos(angleRad) * (radius - 25);
                const labelY = centerY + Math.sin(angleRad) * (radius - 25) + 3;
                ctx.fillText(Math.abs(angle).toString(), labelX, labelY);
            }
        }

        // Current bank angle indicator (triangle)
        const currentRoll = smoothedValues.roll;
        const rollRad = (currentRoll - 90) * Math.PI / 180;

        ctx.fillStyle = COLORS.TEXT_YELLOW;
        ctx.beginPath();
        const indicatorX = centerX + Math.cos(rollRad) * radius;
        const indicatorY = centerY + Math.sin(rollRad) * radius;
        ctx.moveTo(indicatorX, indicatorY);
        ctx.lineTo(indicatorX - 5, indicatorY - 10);
        ctx.lineTo(indicatorX + 5, indicatorY - 10);
        ctx.closePath();
        ctx.fill();
    }

    /**
     * Element #2: Draw Crosstrack Error and Turn Rate
     */
    function drawCrosstrackAndTurnRate() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const y = 20;

        // Background panel
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(centerX - 80, y, 160, 25);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(centerX - 80, y, 160, 25);

        // Crosstrack error display
        const crosstrack = smoothedValues.crosstrackError;
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`XTE: ${crosstrack.toFixed(1)}m`, centerX - 40, y + 16);

        // Turn rate display
        const turnRate = smoothedValues.turnRate;
        ctx.fillText(`T: ${turnRate.toFixed(1)}°/s`, centerX + 40, y + 16);
    }

    /**
     * Element #5: Draw Telemetry Link Quality
     */
    function drawTelemetryLinkQuality() {
        const x = DISPLAY.WIDTH - 150;
        const y = 20;

        // Calculate link quality (simulated for now)
        const linkQuality = telemetryData.connected ? 95 : 0;
        const signalBars = Math.floor(linkQuality / 20);

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 120, 25);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 120, 25);

        // Link quality text
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`LINK: ${linkQuality}%`, x + 5, y + 16);

        // Signal strength bars
        for (let i = 0; i < 5; i++) {
            const barHeight = 3 + (i * 2);
            const barColor = i < signalBars ? COLORS.TEXT_GREEN : COLORS.TEXT_WHITE;
            ctx.fillStyle = barColor;
            ctx.fillRect(x + 80 + (i * 6), y + 15 - barHeight, 4, barHeight);
        }
    }

    /**
     * Element #6: Draw GPS Time
     */
    function drawGPSTime() {
        const x = DISPLAY.WIDTH - 120;
        const y = 50;

        // Get current time (GPS time would come from telemetry)
        const now = new Date();
        const timeString = now.toISOString().substr(11, 8); // HH:MM:SS format

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 110, 20);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 110, 20);

        // GPS time display
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`GPS: ${timeString}`, x + 55, y + 14);
    }

    /**
     * Element #9: Draw Groundspeed Display
     */
    function drawGroundspeedDisplay() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const y = DISPLAY.HEIGHT - 60;

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(centerX - 50, y, 100, 25);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(centerX - 50, y, 100, 25);

        // Groundspeed value
        const groundspeed = smoothedValues.groundspeed;
        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.font = 'bold 14px monospace';
        ctx.textAlign = 'center';
        ctx.fillText(`GS: ${Math.round(groundspeed)}kt`, centerX, y + 17);
    }

    /**
     * Element #10: Draw Battery Status (Upper Left)
     */
    function drawBatteryStatus() {
        const x = 10;
        const y = 10;

        const voltage = telemetryData.battery_voltage || 0;
        const current = telemetryData.current || 0;

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 120, 45);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 120, 45);

        // Battery voltage
        ctx.fillStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
        ctx.font = '12px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`Bat: ${voltage.toFixed(2)}V`, x + 5, y + 16);

        // Current draw
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.fillText(`Cur: ${current.toFixed(1)}A`, x + 5, y + 32);

        // Battery icon
        ctx.strokeStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 90, y + 8, 20, 12);
        ctx.fillRect(x + 110, y + 11, 3, 6);

        // Battery fill level
        const fillLevel = Math.max(0, Math.min(1, (voltage - 10) / 2.6)); // 10V to 12.6V range
        ctx.fillStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
        ctx.fillRect(x + 92, y + 10, 16 * fillLevel, 8);
    }

    /**
     * Element #13: Draw GPS Status
     */
    function drawGPSStatus() {
        const x = 10;
        const y = DISPLAY.HEIGHT - 80;

        // Determine GPS status
        const lat = telemetryData.lat || 0;
        const lon = telemetryData.lon || 0;
        const numSats = telemetryData.gps_nsat || 0;

        let gpsStatus = 'NO FIX';
        let statusColor = COLORS.ALERT_RED;

        if (numSats >= 6) {
            gpsStatus = '3D FIX';
            statusColor = COLORS.TEXT_GREEN;
        } else if (numSats >= 4) {
            gpsStatus = '2D FIX';
            statusColor = COLORS.WARNING_YELLOW;
        }

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 120, 35);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 120, 35);

        // GPS status text
        ctx.fillStyle = statusColor;
        ctx.font = 'bold 12px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`GPS: ${gpsStatus}`, x + 5, y + 16);

        // Satellite count
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '10px monospace';
        ctx.fillText(`Sats: ${numSats}`, x + 5, y + 30);

        // Position display (6 decimal precision)
        ctx.font = '8px monospace';
        if (lat !== 0 && lon !== 0) {
            ctx.fillText(`${lat.toFixed(6)}`, x + 60, y + 16);
            ctx.fillText(`${lon.toFixed(6)}`, x + 60, y + 26);
        } else {
            ctx.fillText('---.------', x + 60, y + 16);
            ctx.fillText('---.------', x + 60, y + 26);
        }
    }

    /**
     * Element #14: Draw Distance to Waypoint and Current Waypoint Number
     */
    function drawWaypointDistance() {
        const x = DISPLAY.WIDTH - 140;
        const y = DISPLAY.HEIGHT - 80;

        // Waypoint information (would come from mission data)
        const currentWaypoint = telemetryData.current_waypoint || 0;
        const waypointDistance = telemetryData.waypoint_distance || 0;

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(x, y, 130, 35);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 130, 35);

        // Waypoint info
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.font = '12px monospace';
        ctx.textAlign = 'left';

        if (currentWaypoint > 0) {
            ctx.fillText(`WPT ${currentWaypoint}`, x + 5, y + 16);
            ctx.fillText(`${waypointDistance.toFixed(1)} m`, x + 5, y + 30);
        } else {
            ctx.fillText('NO WPT', x + 5, y + 16);
            ctx.fillText('--- m', x + 5, y + 30);
        }

        // Waypoint icon
        ctx.strokeStyle = COLORS.TEXT_GREEN;
        ctx.lineWidth = 2;
        ctx.beginPath();
        ctx.arc(x + 100, y + 18, 8, 0, Math.PI * 2);
        ctx.stroke();
        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.beginPath();
        ctx.arc(x + 100, y + 18, 3, 0, Math.PI * 2);
        ctx.fill();
    }

    /**
     * Element #15: Draw Current Flight Mode
     */
    function drawFlightMode() {
        const centerX = DISPLAY.ATTITUDE_CENTER_X;
        const y = DISPLAY.HEIGHT - 40;

        const armed = telemetryData.armed;
        const mode = telemetryData.mode || 'UNKNOWN';
        const armedText = armed ? 'ARMED' : 'DISARMED';

        // Background
        ctx.fillStyle = COLORS.STATUS_BG;
        ctx.fillRect(centerX - 100, y, 200, 30);

        // Border
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(centerX - 100, y, 200, 30);

        // Flight mode
        ctx.fillStyle = COLORS.TEXT_GREEN;
        ctx.font = 'bold 16px Arial';
        ctx.textAlign = 'center';
        ctx.fillText(mode, centerX - 50, y + 20);

        // Armed status
        const armedColor = armed ? COLORS.ALERT_RED : COLORS.TEXT_GREEN;
        ctx.fillStyle = armedColor;
        ctx.font = 'bold 14px Arial';
        ctx.fillText(armedText, centerX + 50, y + 20);
    }

    /**
     * Handle Telemetry Update
     */
    function handleTelemetryUpdate(event) {
        const data = event.detail || event;
        if (data) {
            telemetryData = { ...telemetryData, ...data };
        }
    }

    /**
     * Handle Connection Change
     */
    function handleConnectionChange(event) {
        const data = event.detail || event;
        if (data && !data.connected) {
            telemetryData = {};
        }
    }

    /**
     * Handle Resize
     */
    function handleResize() {
        setTimeout(() => {
            setupHighDPI();
        }, 100);
    }

    /**
     * Public API
     */
    return {
        initialize: initialize,
        getTelemetryData: () => ({ ...telemetryData }),
        onTelemetryUpdate: handleTelemetryUpdate,
        onConnectionChange: handleConnectionChange,
        onResize: handleResize,
        destroy: () => {
            if (animationFrameId) {
                cancelAnimationFrame(animationFrameId);
            }
        }
    };
})();

