/**
 * Elements #1 & #8: Draw Airspeed Tape (Left Side Vertical Tape)
 */
function drawAirspeedTape() {
    const x = 10;
    const width = 90;
    const centerY = DISPLAY.ATTITUDE_CENTER_Y;
    const height = 300;

    // No background - transparent overlay on sky/ground
    // Border only for definition
    ctx.strokeStyle = COLORS.TICKER_BORDER;
    ctx.lineWidth = 1;
    ctx.strokeRect(x, centerY - height/2, width, height);

    // Speed scale
    const airspeed = smoothedValues.airspeed;
    const tickSpacing = 15; // pixels per 5 knots
    const speedPerTick = 5;

    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.font = '12px monospace';
    ctx.textAlign = 'right';

    for (let i = -10; i <= 10; i++) {
        const speed = Math.round((airspeed + (i * speedPerTick)) / speedPerTick) * speedPerTick;
        if (speed < 0) continue;

        const tickY = centerY + (i * tickSpacing);
        if (tickY < centerY - height/2 || tickY > centerY + height/2) continue;

        // Major tick marks every 10 knots
        if (speed % 10 === 0) {
            ctx.strokeStyle = COLORS.TEXT_WHITE;
            ctx.lineWidth = 2;
            ctx.beginPath();
            ctx.moveTo(x + width - 15, tickY);
            ctx.lineTo(x + width - 5, tickY);
            ctx.stroke();

            // Speed labels
            ctx.fillText(speed.toString(), x + width - 20, tickY + 4);
        } else {
            // Minor tick marks
            ctx.strokeStyle = COLORS.TEXT_WHITE;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(x + width - 10, tickY);
            ctx.lineTo(x + width - 5, tickY);
            ctx.stroke();
        }
    }

    // Current airspeed indicator (highlighted box with transparent background)
    const currentY = centerY;
    ctx.strokeStyle = COLORS.TEXT_GREEN;
    ctx.lineWidth = 2;
    ctx.strokeRect(x + width - 35, currentY - 10, 30, 20);

    ctx.fillStyle = COLORS.TEXT_GREEN;
    ctx.font = 'bold 14px monospace';
    ctx.textAlign = 'center';
    ctx.fillText(Math.round(airspeed).toString(), x + width - 20, currentY + 5);

    // Speed label
    ctx.fillStyle = COLORS.TEXT_WHITE;
    ctx.font = '10px Arial';
    ctx.textAlign = 'center';
    ctx.fillText('AIRSPEED', x + width/2, x + 15);
}

