    /**
     * Element #10: Draw Battery Status (Upper Left)
     */
    function drawBatteryStatus() {
        const x = 10;
        const y = 10;

        const voltage = telemetryData.battery_voltage || 0;
        const current = telemetryData.current || 0;

        // NO background - completely transparent overlay

        // Border only for visual definition
        ctx.strokeStyle = COLORS.TEXT_WHITE;
        ctx.lineWidth = 1;
        ctx.strokeRect(x, y, 120, 45);

        // Battery voltage
        ctx.fillStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
        ctx.font = '12px monospace';
        ctx.textAlign = 'left';
        ctx.fillText(`Bat: ${voltage.toFixed(2)}V`, x + 5, y + 16);

        // Current draw
        ctx.fillStyle = COLORS.TEXT_WHITE;
        ctx.fillText(`Cur: ${current.toFixed(1)}A`, x + 5, y + 32);

        // Battery icon
        ctx.strokeStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
        ctx.lineWidth = 2;
        ctx.strokeRect(x + 90, y + 8, 20, 12);
        ctx.fillRect(x + 110, y + 11, 3, 6);

        // Battery fill level
        const fillLevel = Math.max(0, Math.min(1, (voltage - 10) / 2.6)); // 10V to 12.6V range
        ctx.fillStyle = voltage > 11.0 ? COLORS.TEXT_GREEN : COLORS.ALERT_RED;
        ctx.fillRect(x + 92, y + 10, 16 * fillLevel, 8);
