        } else if (alt % 50 === 0) {
            // Medium tick marks every 50 feet
            ctx.strokeStyle = COLORS.TEXT_WHITE;
            ctx.lineWidth = 1;
            ctx.beginPath();
            ctx.moveTo(x + 5, tickY);
            ctx.lineTo(x + 15, tickY);
            ctx.stroke();
