/**
 * Element #12: Draw Aircraft Attitude Indication (Fixed Yellow Symbol) - CENTERED AT 320,240
 */
function drawAircraftAttitude() {
    // CRITICAL: Use exact center coordinates (320, 240) for 640x480 canvas
    const centerX = 320;  // Exact middle of 640px width
    const centerY = 240;  // Exact middle of 480px height

    // Aircraft symbol (fixed to screen, not affected by attitude)
    ctx.strokeStyle = COLORS.TEXT_YELLOW;
    ctx.fillStyle = COLORS.TEXT_YELLOW;
    ctx.lineWidth = 4;

    // Main horizontal reference line (wings)
    ctx.beginPath();
    ctx.moveTo(centerX - 50, centerY);
    ctx.lineTo(centerX - 15, centerY);
    ctx.moveTo(centerX + 50, centerY);
    ctx.lineTo(centerX + 15, centerY);
    ctx.stroke();

    // Center triangle/arrow pointing forward (perfectly centered)
    ctx.beginPath();
    ctx.moveTo(centerX, centerY - 8);
    ctx.lineTo(centerX - 8, centerY + 8);
    ctx.lineTo(centerX + 8, centerY + 8);
    ctx.closePath();
    ctx.fill();

    // Center dot (perfectly centered)
    ctx.beginPath();
    ctx.arc(centerX, centerY, 3, 0, Math.PI * 2);
    ctx.fill();
}

